namespace sv_9da05be413c24a25b5986d2741c632a7.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Components subscribe to OnChange to react when any other component mutates the theme.
/// </summary>
public class ThemeService
{
    private ThemeMode _mode = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Mode
    {
        get => _mode;
        set
        {
            if (_mode == value) return;
            _mode = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* 
    Interactive component embedded in the static MainLayout.
    It subscribes to ThemeService and applies theme via CSS variables / data attributes.
    Because it has its own @rendermode, it joins the circuit and can re-render reactively.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<div class="theme-wrapper"
     data-bs-theme="@ResolvedTheme"
     style="--accent-color: @Theme.AccentColor;">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    private string ResolvedTheme => Theme.Mode switch
    {
        ThemeMode.Dark => "dark",
        ThemeMode.Light => "light",
        _ => "light" // System fallback; JS could refine this
    };

    protected override void OnInitialized()
    {
        Theme.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        Theme.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<span class="badge" style="background-color: @Theme.AccentColor;">
    @Theme.Mode.ToString()
</span>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        Theme.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme Mode</label>
    <select class="form-select" @bind="SelectedMode">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="AccentColor" @bind:event="oninput" />
</div>

<p>
    Current: <strong>@Theme.Mode</strong> &mdash;
    Accent: <span style="color: @Theme.AccentColor;">@Theme.AccentColor</span>
</p>

@code {
    private ThemeMode SelectedMode
    {
        get => Theme.Mode;
        set => Theme.Mode = value;
    }

    private string AccentColor
    {
        get => Theme.AccentColor;
        set => Theme.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        Theme.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        Theme.OnChange -= StateHasChanged;
    }
}

